// Auto-generated processed datasets for GROW Kerala Agricultural Intelligence
export interface ProcessedCultivationCost {
  district: string;
  crop: string;
  year: string;
  land_preparation: number;
  seeds_planting_material: number;
  fertilizers: number;
  labour: number;
  irrigation: number;
  pest_management: number;
  harvesting: number;
  transport: number;
  other_costs: number;
  total_cost_per_hectare: number;
  source: string;
}

export interface ProcessedMarketArrival {
  observation_date: string;
  state: string;
  district: string;
  market: string;
  commodity: string;
  variety: string;
  arrival_quantity: number;
  arrival_unit: string;
  source: string;
  retrieved_at: string;
  source_record_id: string;
}

export interface ProcessedDemand {
  date: string;
  district: string;
  market: string;
  crop: string;
  arrivals_tonnes: number;
  modal_price: number;
  source: string;
}

export interface ProcessedCropCalendar {
  district: string;
  crop: string;
  season: string;
  sowing_start_month: number;
  sowing_end_month: number;
  harvest_start_month: number;
  harvest_end_month: number;
  duration_days: number;
  source: string;
}

export interface ProcessedMarketPrice {
  date: string;
  district: string;
  market: string;
  crop: string;
  variety: string;
  min_price: number;
  max_price: number;
  modal_price: number;
  price_unit: string;
  source: string;
}

